import React, { useState, useEffect } from 'react';

export default function Header() {
  const [isMobile, setIsMobile] = useState(false);

  // Handle window resizing for full responsiveness
  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    handleResize(); // Initial check
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <>
      {/* Injecting keyframes for the infinite RGB animation */}
      <style>
        {`
          @keyframes rgbGlow {
            0% { filter: hue-rotate(0deg); }
            100% { filter: hue-rotate(360deg); }
          }
          .rgb-animated-logo {
            animation: rgbGlow 6s linear infinite;
          }
          .nav-link:hover {
            color: #00D2C4 !important;
            transform: translateY(-1px);
          }
          .cta-button:hover {
            background-color: #00b3a6 !important;
            box-shadow: 0 0 15px rgba(0, 210, 196, 0.5);
            transform: scale(1.05);
          }
        `}
      </style>

      <nav style={{
        backgroundColor: '#070F1E',
        borderBottom: '1px solid rgba(255, 255, 255, 0.05)',
        padding: isMobile ? '12px 16px' : '16px 32px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        position: 'sticky',
        top: 0,
        zIndex: 50,
        width: '100%',
        boxSizing: 'border-box'
      }}>
        {/* Logo & Brand Section */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div className="rgb-animated-logo" style={{
            width: '42px',
            height: '42px',
            borderRadius: '10px',
            background: 'linear-gradient(135deg, #00D2C4, #ff007f, #7928ca, #0070f3)',
            backgroundSize: '300% 300%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: '#fff',
            fontWeight: 'bold',
            padding: '2px', // Border effect wrapper
            boxShadow: '0 4px 12px rgba(0, 210, 196, 0.3)'
          }}>
            <div style={{
              width: '100%',
              height: '100%',
              backgroundColor: '#070F1E',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              overflow: 'hidden'
            }}>
              {/* Change src to your actual asset path, e.g., require('../assets/logo.png') */}
              <img 
                src="/assets/logo.png" 
                alt="Logo" 
                onError={(e) => { e.target.style.display = 'none'; }} 
                style={{ width: '100%', height: '100%', objectFit: 'cover' }}
              />
              <span style={{ position: 'absolute', fontSize: '14px', color: '#00D2C4' }}>VA</span>
            </div>
          </div>
          <span style={{ 
            color: '#fff', 
            fontSize: isMobile ? '16px' : '18px', 
            fontWeight: 'bold',
            letterSpacing: '0.5px' 
          }}>
            Vighnavi Academy
          </span>
        </div>

        {/* Navigation Links (Hidden or stacked gracefully on mobile) */}
        {!isMobile && (
          <div style={{ display: 'flex', gap: '28px', fontSize: '14px', fontWeight: '500' }}>
            <a href="#home" className="nav-link" style={{ color: '#d1d5db', textDecoration: 'none', transition: 'all 0.2s ease' }}>Home</a>
            <a href="#about" className="nav-link" style={{ color: '#d1d5db', textDecoration: 'none', transition: 'all 0.2s ease' }}>About Us</a>
            <a href="#courses" className="nav-link" style={{ color: '#d1d5db', textDecoration: 'none', transition: 'all 0.2s ease' }}>Courses</a>
            <a href="#testimonials" className="nav-link" style={{ color: '#d1d5db', textDecoration: 'none', transition: 'all 0.2s ease' }}>Testimonials</a>
          </div>
        )}

        {/* Action Button */}
        <div>
          <a href="#contact" className="cta-button" style={{
            backgroundColor: '#00D2C4',
            color: '#000',
            padding: isMobile ? '8px 14px' : '10px 22px',
            borderRadius: '25px',
            textDecoration: 'none',
            fontWeight: '600',
            fontSize: isMobile ? '13px' : '14px',
            display: 'inline-block',
            transition: 'all 0.3s ease'
          }}>
            Book Consultation
          </a>
        </div>
      </nav>
    </>
  );
}
